public class binarytrees {
    private static final class TreeNode {
        private final TreeNode left;
        private final TreeNode right;

        TreeNode(TreeNode left, TreeNode right) {
            this.left = left;
            this.right = right;
        }
    }

    private static TreeNode bottomUpTree(int depth) {
        if (depth <= 0) {
            return new TreeNode(null, null);
        }
        return new TreeNode(
                bottomUpTree(depth - 1),
                bottomUpTree(depth - 1)
        );
    }

    private static long itemCheck(TreeNode tree) {
        if (tree.left == null) {
            return 1;
        }
        return 1 + itemCheck(tree.left) + itemCheck(tree.right);
    }

    public static void main(String[] args) {
        int n = Integer.parseInt(args[0]);

        TreeNode stretchTree = bottomUpTree(n + 1);
        long stretchCheck = itemCheck(stretchTree);
        stretchTree = null;

        TreeNode longLivedTree = bottomUpTree(n);
        long longLivedCheck = itemCheck(longLivedTree);

        StringBuilder output = new StringBuilder();
        output.append("stretch tree of depth ")
                .append(n + 1)
                .append("\t check: ")
                .append(stretchCheck)
                .append('\n');

        for (int depth = 4; depth <= n; depth += 2) {
            long iterations = 1L << (n - depth + 4);
            long check = 0;

            for (long i = 0; i < iterations; i++) {
                TreeNode tree = bottomUpTree(depth);
                check += itemCheck(tree);
            }

            output.append(iterations)
                    .append("\t trees of depth ")
                    .append(depth)
                    .append("\t check: ")
                    .append(check)
                    .append('\n');
        }

        output.append("long lived tree of depth ")
                .append(n)
                .append("\t check: ")
                .append(longLivedCheck)
                .append('\n');

        System.out.print(output);
    }
}

